final class CandidateBackgroundHostChecks {
 static void isolate(Context c)throws Exception{AccountBackupHostChecks.isolate(c);for(String name:new String[]{"candidate-tests.sqlite","candidate-background-tests.sqlite"})for(String suffix:new String[]{"","-wal","-shm","-journal"}){File p=c.getDatabasePath(name+suffix);if(p.exists())Files.move(p.toPath(),new File(p+".previous-"+UUID.randomUUID()).toPath());}}
 static String asset(FlowInstrumentation f,String name)throws Exception{try(InputStream in=f.getContext().getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 static void button(FlowInstrumentation f,String tag){f.ui(()->{android.view.View b=f.activity.candidateScreen.findViewWithTag(tag);f.check(b!=null&&b.isEnabled(),tag);b.performClick();});}
 static void await(FlowInstrumentation f,java.util.function.BooleanSupplier condition,String why)throws Exception{long until=SystemClock.elapsedRealtime()+12000;boolean[] done={false};String[] diagnostic={""};while(SystemClock.elapsedRealtime()<until){f.ui(()->{done[0]=condition.getAsBoolean();LocalCandidateScreen s=f.activity.candidateScreen;diagnostic[0]=s==null?"no candidate page":s.state.getText()+"; busy="+s.busy+"; anchor="+s.anchor+"; chosen="+s.chosen+"; generation="+s.generation;});if(done[0])return;Thread.sleep(50);}f.shot("android-v39-failure");throw new AssertionError(why+": "+diagnostic[0]);}
 static void run(FlowInstrumentation f)throws Exception{
  f.check(Build.VERSION.SDK_INT>=35,"device supports honest read-only multi-query transaction");
  boolean components=!f.businessScenario.endsWith("-ui");String safe=components?StoreReadSafetyDeviceChecks.run(f.getTargetContext()):"prior component run, not repeated";if(components)f.check(safe.startsWith("PASS"),safe);
  JSONArray selected=new JSONArray(asset(f,"candidate-background-device-selected-fixture.json"));JSONObject source=new JSONObject(asset(f,"candidate-background-device-source-fixture.json"));
  JSONObject module=components?HostCandidateBackgroundChecks.run(new File(f.activity.getCacheDir(),"candidate-background-v40-"+UUID.randomUUID()),source,selected):new JSONObject().put("notRepeated",true);if(components)f.check(module.getBoolean("passed"),module.toString());
  JSONObject qtBundle=new JSONObject(asset(f,"candidate-background-qt-bundle.json"));JSONObject cross=components?HostCandidateBackgroundChecks.verifyQtBundle(qtBundle):new JSONObject().put("notRepeated",true);if(components){f.check(cross.getBoolean("passed"),"actual Android validates Qt complete bundle");File guards=new File(f.activity.getCacheDir(),"background-ownership-"+UUID.randomUUID());f.check(guards.mkdir(),"new isolated ownership directory");for(String type:new String[]{"empty","unmarked","foreign","damaged"}){File original=new File(guards,type+".sqlite");if(type.equals("empty"))f.check(original.createNewFile(),"owned empty fixture");else if(type.equals("damaged"))Files.write(original.toPath(),"preserved non-SQLite original".getBytes(StandardCharsets.UTF_8));else try(android.database.sqlite.SQLiteDatabase db=android.database.sqlite.SQLiteDatabase.openOrCreateDatabase(original,null)){db.execSQL("PRAGMA user_version=1");if(type.equals("foreign"))db.execSQL("PRAGMA application_id=37");}byte[] before=Files.readAllBytes(original.toPath());HostCandidateBackground guard=new HostCandidateBackground(new File(guards,"source-missing"),new File(guards,"recent-missing"),new File(guards,"leaders-missing"),original);boolean rejected=false;try{guard.putDraft(qtBundle,"",null);}catch(Exception e){rejected=true;}f.check(rejected&&Arrays.equals(before,Files.readAllBytes(original.toPath())),"background refuses unowned "+type+" without byte changes");}}
  f.ui(()->{try{f.check(f.activity.testing,"fixture roster only in isolated host");java.lang.reflect.Field field=MainActivity.class.getDeclaredField("instruments");field.setAccessible(true);List<JSONObject> roster=(List<JSONObject>)field.get(f.activity);roster.clear();for(int i=0;i<selected.length();i++)roster.add(selected.getJSONObject(i));f.activity.localCandidates();f.check(f.activity.candidateScreen.isShown(),"actual internal Java candidate page");f.check(f.activity.candidateScreen.current==null&&!f.activity.candidateScreen.backgroundMode.isChecked(),"v1 default and no auto calculation");f.activity.candidateScreen.chosen.add(selected.getJSONObject(0).getString("id"));f.activity.candidateScreen.render();}catch(Exception e){throw new RuntimeException(e);}});
  button(f,"candidateCalculate");await(f,()->!f.activity.candidateScreen.busy&&f.activity.candidateScreen.anchor.startsWith("draft:"),"v1 preserved calculation");
  final Bundle[] v1={null};f.ui(()->{v1[0]=f.activity.candidateScreen.saveState();f.activity.candidateScreen.backgroundMode.setChecked(true);});button(f,"candidateCalculate");f.ui(()->f.check(f.activity.candidateScreen.state.getText().toString().contains("账户")&&f.activity.candidateScreen.anchor.isEmpty(),"v2 requires explicit account"));
  button(f,"candidateBackgroundAccounts");await(f,()->f.activity.candidateScreen.mode.equals("accounts"),"inline account choices");f.ui(()->{LocalCandidateScreen s=f.activity.candidateScreen;CheckBox box=s.findViewWithTag("candidateAccount:local");f.check(box!=null&&!box.isChecked()&&s.accountScroll.isShown(),"ledger account has no implicit default");f.check(s.findViewWithTag("candidateAccount:paper")==null,"paper account excluded");box.setChecked(true);});button(f,"candidateBackgroundAccountApply");button(f,"candidateCalculate");await(f,()->!f.activity.candidateScreen.busy&&f.activity.candidateScreen.anchor.startsWith("bg-draft:"),"background captures through real Main adapter");
  final String[] digest={""};f.ui(()->{try{LocalCandidateScreen s=f.activity.candidateScreen;f.check(s.current.getString("model").equals("native-local-candidates/v2-background"),"v2 model exact");digest[0]=HostCandidateBackground.digest(s.currentBundle);s.name.setText("明确账户背景快照");}catch(Exception e){throw new RuntimeException(e);}});button(f,"candidateSave");await(f,()->!f.activity.candidateScreen.busy&&f.activity.candidateScreen.anchor.startsWith("bg-saved:"),"named complete bundle saved");
  final Bundle[] saved={null};f.ui(()->{LocalCandidateScreen s=f.activity.candidateScreen;saved[0]=s.saveState();Parcel p=Parcel.obtain();p.writeBundle(saved[0]);f.check(p.dataSize()<16384,"full source not in Binder");p.recycle();s.list.performItemClick(s.list.getChildAt(0),0,0);f.check(s.detail.getText().toString().contains("背景 v2"),"readable contribution/source diagnosis");});f.shot("android-v39-background-detail");
  f.ui(()->f.activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));Thread.sleep(800);f.ui(()->f.check(f.activity.candidateScreen.detailScroll.getHeight()>=f.activity.dp(80),"landscape detail viewport remains usable"));f.shot("android-v39-background-landscape");f.ui(()->f.activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));
  button(f,"candidateBackgroundAccounts");await(f,()->f.activity.candidateScreen.mode.equals("accounts"),"account panel reopened");f.ui(()->{f.check(f.activity.closeInternalReader(),"back closes inline choices first");f.check(f.activity.candidateScreen.isShown(),"back does not leave parent prematurely");f.activity.goHome();f.activity.localCandidates();f.activity.candidateScreen.restoreState(saved[0]);});await(f,()->!f.activity.candidateScreen.busy&&f.activity.candidateScreen.currentBundle!=null,"saved bundle replay");
  f.ui(()->{try{f.check(HostCandidateBackground.digest(f.activity.candidateScreen.currentBundle).equals(digest[0]),"replay does not recompute background");f.activity.candidateScreen.restoreState(v1[0]);}catch(Exception e){throw new RuntimeException(e);}});await(f,()->!f.activity.candidateScreen.busy&&f.activity.candidateScreen.current!=null&&!f.activity.candidateScreen.backgroundMode.isChecked(),"old v1 draft still readable");
  f.ui(()->{f.activity.candidateScreen.restoreState(saved[0]);});await(f,()->!f.activity.candidateScreen.busy&&f.activity.candidateScreen.currentBundle!=null,"return to named v2");f.shot("android-v39-background-results");
  File report=new File(f.activity.getExternalFilesDir(null),f.shotFolder+"/candidate-background-device.json");JSONObject out=new JSONObject().put("module",module).put("storeSafety",safe).put("qtCrossBundle",cross).put("scope","isolated actual Java Views/SQLite; not live feed, online AI, ARM or full migration");Files.write(report.toPath(),out.toString(2).getBytes(StandardCharsets.UTF_8));f.ui(()->f.activity.goHome());
 }
}
